-- Rebuild Medina Book 4 lesson 4 strictly from the supplied Arabic sharh.
-- Canonical PDF pages: 13-20. DOC text was used only for extraction and checked against the PDF.
begin;

do $migration$
declare
  existing_count integer;
begin
  select count(*) into existing_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '4';
  if existing_count <> 9 then
    raise exception 'Expected 9 Book 4 lesson 4 rules, found %', existing_count;
  end if;
end $migration$;

with incoming(sort_order, title, content, summary, rule_ar) as (
  values
    (1, 'بَابُ تَفَاعَلَ (порода تَفَاعَلَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">بَابُ تَفَاعَلَ مَزِيدٌ بِالتَّاءِ وَالْأَلِفِ، وَمَصْدَرُهُ عَلَى وَزْنِ تَفَاعُلٍ. وَمِنْ مَعَانِيهِ الْمُشَارَكَةُ وَإِظْهَارُ مَا لَيْسَ فِي الْبَاطِنِ. وَيَجُوزُ حَذْفُ إِحْدَى التَّاءَيْنِ مِنْ مُضَارِعِهِ الْمَبْدُوءِ بِالتَّاءِ.</span><p class="rule-study-text">В породе تَفَاعَلَ добавлены ت и алиф, а масдар строится по модели تَفَاعُلٌ. Шарх выделяет взаимное участие и внешнее изображение того, чего нет внутри. В начинающейся с ت форме настоящего-будущего одну из двух ت можно удалить.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">حَرْفَا الزِّيَادَةِ: التَّاءُ وَالْأَلِفُ</span><span class="rule-term-ru">добавочные элементы — ت и алиф</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ: تَفَاعُلٌ</span><span class="rule-term-ru">масдар по модели تَفَاعُلٌ</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الْمُشَارَكَةُ</span><span class="rule-term-ru">взаимное участие</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">إِظْهَارُ مَا لَيْسَ فِي الْبَاطِنِ</span><span class="rule-term-ru">внешнее изображение отсутствующего внутреннего состояния</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Два значения</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">تَصَافَحَ الرَّجُلَانِ. تَقَاتَلَ الْجُنُودُ.</span><span class="rule-example-ru">Двое мужчин пожали друг другу руки. Воины сражались друг с другом.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">تَبَاكَى الطِّفْلُ. تَعَامَى الرَّجُلُ.</span><span class="rule-example-ru">Ребёнок притворился плачущим. Мужчина притворился слепым.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Производные формы шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمَاضِي</span><span class="rule-table-ru">прошедшее</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمُضَارِعُ</span><span class="rule-table-ru">настояще-будущее</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْأَمْرُ</span><span class="rule-table-ru">повелительное</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-table-ru">действующее причастие</span></th><th><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">اسْمُ الْمَفْعُولِ</span><span class="rule-table-ru">страдательное причастие</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَدَارَكَ</span><span class="rule-table-ru">настиг, восполнил</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَتَدَارَكُ</span><span class="rule-table-ru">настигает, восполняет</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَدَارَكْ</span><span class="rule-table-ru">настигни, восполни</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَدَارُكٌ</span><span class="rule-table-ru">настигание, восполнение</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُتَدَارِكٌ</span><span class="rule-table-ru">настигающий, восполняющий</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مُتَدَارَكٌ</span><span class="rule-table-ru">настигнутое, восполненное</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَعَامَى</span><span class="rule-table-ru">притворился слепым</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَتَعَامَى</span><span class="rule-table-ru">притворяется слепым</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَعَامَ</span><span class="rule-table-ru">притворись слепым</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَعَامٍ (أَصْلُهُ تَعَامُيٌ)</span><span class="rule-table-ru">притворная слепота; исходная форма تَعَامُيٌ</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُتَعَامٍ</span><span class="rule-table-ru">притворяющийся слепым</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَازِمٌ</span><span class="rule-table-ru">непереходный; страдательное причастие не приводится</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَعَاوَنَ</span><span class="rule-table-ru">сотрудничал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَتَعَاوَنُ</span><span class="rule-table-ru">сотрудничает</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">تَعَاوَنْ</span><span class="rule-table-ru">сотрудничай</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَعَاوُنٌ</span><span class="rule-table-ru">сотрудничество</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُتَعَاوِنٌ</span><span class="rule-table-ru">сотрудничающий</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَازِمٌ</span><span class="rule-table-ru">непереходный; страдательное причастие не приводится</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Удаление одной ت</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿وَلَا تَعَاوَنُواْ عَلَى ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِ﴾</span><span class="rule-example-ru">И не помогайте друг другу в грехе и вражде. Исходная форма: وَلَا تَتَعَاوَنُوا.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿وَلَا تَنَابَزُواْ بِٱلۡأَلۡقَٰبِ﴾</span><span class="rule-example-ru">И не называйте друг друга оскорбительными прозвищами. Исходная форма: وَلَا تَتَنَابَزُوا.</span></div></div></div></div>', 'В породе تَفَاعَلَ добавлены ت и алиф, а масдар строится по модели تَفَاعُلٌ. Шарх выделяет взаимное участие и внешнее изображение того, чего нет внутри. В начинающейся с ت форме настоящего-будущего одну из двух ت можно удалить.', 'بَابُ تَفَاعَلَ مَزِيدٌ بِالتَّاءِ وَالْأَلِفِ، وَمَصْدَرُهُ عَلَى وَزْنِ تَفَاعُلٍ. وَمِنْ مَعَانِيهِ الْمُشَارَكَةُ وَإِظْهَارُ مَا لَيْسَ فِي الْبَاطِنِ. وَيَجُوزُ حَذْفُ إِحْدَى التَّاءَيْنِ مِنْ مُضَارِعِهِ الْمَبْدُوءِ بِالتَّاءِ.'),
    (2, 'حَذْفُ حَرْفِ الْجَرِّ قَبْلَ الْمَصْدَرِ الْمُؤَوَّلِ (удаление предлога перед развёрнутым масдаром)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-jarr" dir="rtl" lang="ar">يَجُوزُ حَذْفُ حَرْفِ الْجَرِّ الْوَاقِعِ قَبْلَ الْمَصْدَرِ الْمُؤَوَّلِ.</span><p class="rule-study-text">Предлог, непосредственно стоящий перед конструкцией, равной масдару, разрешается опустить. Шарх показывает исходный предлог через восстановленный вариант каждого примера.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Явная форма и восстановленный предлог</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">التَّقْدِيرُ</span><span class="rule-table-ru">восстановленная форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَمَرَنَا اللَّهُ أَنْ نُصَلِّيَ.</span><span class="rule-table-ru">предлог опущен</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">أَمَرَنَا اللَّهُ بِأَنْ نُصَلِّيَ.</span><span class="rule-table-ru">восстановлен предлог بِـ</span></td><td><span class="rule-table-ru">Аллах повелел нам совершать молитву.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَعُوذُ بِاللَّهِ أَنْ أَكُونَ مِنَ الْجَاهِلِينَ.</span><span class="rule-table-ru">предлог перед масдаром опущен</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">أَعُوذُ بِاللَّهِ مِنْ أَنْ أَكُونَ مِنَ الْجَاهِلِينَ.</span><span class="rule-table-ru">восстановлен предлог مِنْ</span></td><td><span class="rule-table-ru">Я прибегаю к защите Аллаха от того, чтобы оказаться среди невежд.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿شَهِدَ ٱللَّهُ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا هُوَ﴾</span><span class="rule-example-ru">Аллах засвидетельствовал, что нет божества, кроме Него. Восстановленный смысл: بِأَنَّهُ لَا إِلَهَ إِلَّا هُوَ.</span></div></div></div></div>', 'Предлог, непосредственно стоящий перед конструкцией, равной масдару, разрешается опустить. Шарх показывает исходный предлог через восстановленный вариант каждого примера.', 'يَجُوزُ حَذْفُ حَرْفِ الْجَرِّ الْوَاقِعِ قَبْلَ الْمَصْدَرِ الْمُؤَوَّلِ.'),
    (3, 'حَذْفُ الْوَاوِ مِنَ الْمُحَذَّرِ مِنْهُ (удаление وَ из конструкции предостережения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">يَجُوزُ حَذْفُ الْوَاوِ مِنَ الْمُحَذَّرِ مِنْهُ إِذَا كَانَ مَصْدَرًا مُؤَوَّلًا.</span><p class="rule-study-text">Если предмет предостережения выражен развёрнутым масдаром أَنْ + глагол, соединительную وَ разрешается опустить.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Преобразование примеров</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَعَ الْوَاوِ</span><span class="rule-table-ru">с وَ и явным масдаром</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بِدُونِ الْوَاوِ</span><span class="rule-table-ru">без وَ, с развёрнутым масдаром</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِيَّاكَ وَالْكَذِبَ.</span><span class="rule-table-ru">предостерегаю тебя от лжи</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِيَّاكَ أَنْ تَكْذِبَ.</span><span class="rule-table-ru">предостерегаю тебя от того, чтобы ты лгал</span></td><td><span class="rule-table-ru">Остерегайся лгать.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِيَّاكُمْ وَالنَّوْمَ فِي الْفَصْلِ.</span><span class="rule-table-ru">предостерегаю вас от сна на занятии</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِيَّاكُمْ أَنْ تَنَامُوا فِي الْفَصْلِ.</span><span class="rule-table-ru">предостерегаю вас от того, чтобы вы спали на занятии</span></td><td><span class="rule-table-ru">Не спите на занятии.</span></td></tr></tbody></table></div></div></div>', 'Если предмет предостережения выражен развёрнутым масдаром أَنْ + глагол, соединительную وَ разрешается опустить.', 'يَجُوزُ حَذْفُ الْوَاوِ مِنَ الْمُحَذَّرِ مِنْهُ إِذَا كَانَ مَصْدَرًا مُؤَوَّلًا.'),
    (4, 'مَصْدَرُ الْمِثَالِ الْوَاوِيِّ (масдар глагола с первой корневой وَاو)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">لِلْمِثَالِ الْوَاوِيِّ مَصْدَرَانِ: أَحَدُهُمَا بِإِبْقَاءِ الْوَاوِ، وَالْآخَرُ بِحَذْفِهَا وَالتَّعْوِيضِ عَنْهَا بِتَاءٍ فِي آخِرِ الْمَصْدَرِ.</span><p class="rule-study-text">Шарх приводит два типа масдара начально-слабого глагола на و: с сохранением первой коренной либо с её удалением и компенсацией буквой ة в конце.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Оба типа масдара</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْفِعْلُ</span><span class="rule-table-ru">глагол</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَعَ الْوَاوِ</span><span class="rule-table-ru">масдар с сохранённой و</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَعَ الْحَذْفِ وَالتَّعْوِيضِ</span><span class="rule-table-ru">масдар с удалением و и компенсацией ة</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَعَدَ</span><span class="rule-table-ru">обещал</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَعْدٌ</span><span class="rule-table-ru">обещание</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">عِدَةٌ</span><span class="rule-table-ru">обещание</span></td><td><span class="rule-table-ru">два масдара одного глагола</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَعَظَ</span><span class="rule-table-ru">увещевал</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَعْظٌ</span><span class="rule-table-ru">увещевание</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">عِظَةٌ</span><span class="rule-table-ru">назидание</span></td><td><span class="rule-table-ru">сохранение или компенсация первой و</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَزَنَ</span><span class="rule-table-ru">взвесил</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَزْنٌ</span><span class="rule-table-ru">вес, взвешивание</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">زِنَةٌ</span><span class="rule-table-ru">вес</span></td><td><span class="rule-table-ru">сохранение или компенсация первой و</span></td></tr></tbody></table></div></div></div>', 'Шарх приводит два типа масдара начально-слабого глагола на و: с сохранением первой коренной либо с её удалением и компенсацией буквой ة в конце.', 'لِلْمِثَالِ الْوَاوِيِّ مَصْدَرَانِ: أَحَدُهُمَا بِإِبْقَاءِ الْوَاوِ، وَالْآخَرُ بِحَذْفِهَا وَالتَّعْوِيضِ عَنْهَا بِتَاءٍ فِي آخِرِ الْمَصْدَرِ.'),
    (5, 'مَعْنَى لَيْتَ (значение частицы لَيْتَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">تُفِيدُ لَيْتَ التَّمَنِّيَ، وَهُوَ طَلَبُ مَا لَا طَمَعَ فِي حُصُولِهِ، أَوْ طَلَبُ مَا يَصْعُبُ حُصُولُهُ مَعَ إِمْكَانِهِ.</span><p class="rule-study-text">لَيْتَ выражает пожелание двух видов: недостижимого, на получение которого нет надежды, либо возможного, но труднодостижимого в данный момент.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Два вида пожелания</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">طَلَبُ مَا لَا طَمَعَ فِيهِ</span><span class="rule-table-ru">пожелание недостижимого</span></td><td><span class="rule-table-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿يَٰلَيۡتَنِي كُنتُ تُرَٰبَۢا﴾</span><span class="rule-table-ru">О, если бы я был прахом!</span></td><td><span class="rule-table-ru">получить желаемое невозможно</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">طَلَبُ مَا لَا طَمَعَ فِيهِ</span><span class="rule-table-ru">пожелание недостижимого</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَيْتَنِي طَائِرٌ. لَيْتَ الشَّبَابَ يَعُودُ.</span><span class="rule-table-ru">О, если бы я был птицей. О, если бы молодость вернулась.</span></td><td><span class="rule-table-ru">невозможное пожелание</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَا فِيهِ عُسْرٌ</span><span class="rule-table-ru">труднодостижимое, но возможное</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَيْتَ لِي مَالًا كَثِيرًا. لَيْتَنِي عَالِمٌ.</span><span class="rule-table-ru">О, если бы у меня было много денег. О, если бы я был учёным.</span></td><td><span class="rule-table-ru">возможное, но сейчас трудное пожелание</span></td></tr></tbody></table></div></div></div>', 'لَيْتَ выражает пожелание двух видов: недостижимого, на получение которого нет надежды, либо возможного, но труднодостижимого в данный момент.', 'تُفِيدُ لَيْتَ التَّمَنِّيَ، وَهُوَ طَلَبُ مَا لَا طَمَعَ فِي حُصُولِهِ، أَوْ طَلَبُ مَا يَصْعُبُ حُصُولُهُ مَعَ إِمْكَانِهِ.'),
    (6, 'لَا النَّافِيَةُ لِلْجِنْسِ (لَا полного отрицания рода)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">لَا النَّافِيَةُ لِلْجِنْسِ تَنْفِي الْحُكْمَ عَنْ كُلِّ جِنْسِ اسْمِهَا، وَتَعْمَلُ عَمَلَ إِنَّ فَتَنْصِبُ الِاسْمَ وَتَرْفَعُ الْخَبَرَ. وَاسْمُهَا مُضَافٌ، أَوْ شَبِيهٌ بِالْمُضَافِ، أَوْ مُفْرَدٌ؛ فَالْمُضَافُ وَالشَّبِيهُ بِهِ مَنْصُوبَانِ، وَالْمُفْرَدُ مَبْنِيٌّ عَلَى مَا يُنْصَبُ بِهِ فِي مَحَلِّ نَصْبٍ.</span><p class="rule-study-text">Эта لَا отрицает признак у всего рода своего имени и управляет как إِنَّ. Её имя и сказуемое должны быть неопределёнными, сохранять обычный порядок и не соединяться с предлогом. Имя бывает в идафе, подобным идафе либо одиночным.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Условия работы</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الِاسْمُ أَوَّلًا وَالْخَبَرُ ثَانِيًا</span><span class="rule-term-ru">сохраняется исходный порядок: сначала имя, затем сказуемое</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الِاسْمُ وَالْخَبَرُ نَكِرَتَانِ</span><span class="rule-term-ru">имя и сказуемое являются неопределёнными</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar ar-tone-jarr" dir="rtl" lang="ar">أَلَّا تَقْتَرِنَ بِحَرْفِ جَرٍّ</span><span class="rule-term-ru">لَا не должна соединяться с предлогом</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Виды имени لَا</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид имени</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحُكْمُ</span><span class="rule-table-ru">грамматический статус</span></th><th><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُضَافُ</span><span class="rule-table-ru">имя в идафе</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-table-ru">стоит в винительном статусе</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا طَالِبَ عِلْمٍ مَكْرُوهٌ.</span><span class="rule-table-ru">Ни один искатель знания не является ненавистным.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّبِيهُ بِالْمُضَافِ</span><span class="rule-table-ru">подобное идафе</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-table-ru">стоит в винительном статусе</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا طَالِبًا الْعِلْمَ مَكْرُوهٌ.</span><span class="rule-table-ru">Ни один ищущий знание не является ненавистным.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُفْرَدُ</span><span class="rule-table-ru">не идафа и не подобное идафе</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَبْنِيٌّ عَلَى مَا يُنْصَبُ بِهِ</span><span class="rule-table-ru">строится на том признаке, которым выражается его винительный статус</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا طَالِبَ فِي الْفَصْلِ.</span><span class="rule-table-ru">В аудитории нет ни одного студента.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُفْرَدُ</span><span class="rule-table-ru">правильное женское множественное</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مَبْنِيٌّ عَلَى الْكَسْرِ</span><span class="rule-table-ru">строится на касре в винительном месте</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا مُسْلِمَاتِ مُتَبَرِّجَاتٌ.</span><span class="rule-table-ru">Нет мусульманок, выставляющих свою красоту напоказ.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُفْرَدُ</span><span class="rule-table-ru">правильное мужское множественное</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَبْنِيٌّ عَلَى الْيَاءِ</span><span class="rule-table-ru">строится на ي в винительном месте</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا مُسْلِمِينَ كَاذِبُونَ.</span><span class="rule-table-ru">Нет лживых мусульман.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранические примеры шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿ذَٰلِكَ ٱلۡكِتَٰبُ لَا رَيۡبَۛ فِيهِ﴾</span><span class="rule-example-ru">Это Писание — нет сомнения в нём.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿لَآ إِكۡرَاهَ فِي ٱلدِّينِ﴾</span><span class="rule-example-ru">Нет принуждения в религии.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный разбор لَا إِكْرَاهَ فِي الدِّينِ</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">لَا: حَرْفٌ لِنَفْيِ الْجِنْسِ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-example-ru">لَا — неизменяемая на сукуне частица полного отрицания рода без синтаксического места.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">إِكْرَاهَ: اسْمُ لَا النَّافِيَةِ لِلْجِنْسِ مَبْنِيٌّ عَلَى الْفَتْحِ فِي مَحَلِّ نَصْبٍ.</span><span class="rule-example-ru">إِكْرَاهَ — имя لَا, построенное на фатхе и занимающее винительное место.</span></div><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar ar-tone-predicate" dir="rtl" lang="ar">فِي الدِّينِ: الْجَارُّ وَالْمَجْرُورُ فِي مَحَلِّ رَفْعٍ خَبَرُ لَا النَّافِيَةِ لِلْجِنْسِ.</span><span class="rule-example-ru">فِي الدِّينِ — предложная группа, занимающая именительное место сказуемого لَا.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный разбор لَا مُسْلِمَاتِ سَافِرَاتٌ</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">لَا: حَرْفٌ لِنَفْيِ الْجِنْسِ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-example-ru">لَا — неизменяемая на сукуне частица полного отрицания рода без синтаксического места.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">مُسْلِمَاتِ: اسْمُ لَا النَّافِيَةِ لِلْجِنْسِ مَبْنِيٌّ عَلَى الْكَسْرِ فِي مَحَلِّ نَصْبٍ.</span><span class="rule-example-ru">مُسْلِمَاتِ — имя لَا, построенное на касре и занимающее винительное место.</span></div><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar ar-tone-predicate" dir="rtl" lang="ar">سَافِرَاتٌ: خَبَرُ لَا النَّافِيَةِ لِلْجِنْسِ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">سَافِرَاتٌ — сказуемое لَا в именительном статусе с явной даммой.</span></div></div></div></div>', 'Эта لَا отрицает признак у всего рода своего имени и управляет как إِنَّ. Её имя и сказуемое должны быть неопределёнными, сохранять обычный порядок и не соединяться с предлогом. Имя бывает в идафе, подобным идафе либо одиночным.', 'لَا النَّافِيَةُ لِلْجِنْسِ تَنْفِي الْحُكْمَ عَنْ كُلِّ جِنْسِ اسْمِهَا، وَتَعْمَلُ عَمَلَ إِنَّ فَتَنْصِبُ الِاسْمَ وَتَرْفَعُ الْخَبَرَ. وَاسْمُهَا مُضَافٌ، أَوْ شَبِيهٌ بِالْمُضَافِ، أَوْ مُفْرَدٌ؛ فَالْمُضَافُ وَالشَّبِيهُ بِهِ مَنْصُوبَانِ، وَالْمُفْرَدُ مَبْنِيٌّ عَلَى مَا يُنْصَبُ بِهِ فِي مَحَلِّ نَصْبٍ.'),
    (7, 'الْبَدَلُ (приложение-замена الْبَدَلُ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">الْبَدَلُ تَابِعٌ مَقْصُودٌ بِالْحُكْمِ بِلَا وَاسِطَةٍ بَيْنَهُ وَبَيْنَ مَتْبُوعِهِ. وَأَنْوَاعُهُ: بَدَلُ كُلٍّ مِنْ كُلٍّ، وَبَدَلُ بَعْضٍ مِنْ كُلٍّ، وَبَدَلُ اشْتِمَالٍ، وَبَدَلُ الْمُبَايِنِ. وَلَا يُشْتَرَطُ اتِّفَاقُ الْبَدَلِ وَالْمُبْدَلِ مِنْهُ فِي التَّعْرِيفِ وَالتَّنْكِيرِ.</span><p class="rule-study-text">الْبَدَلُ — зависимый член, на который непосредственно направлено сообщение. Шарх разбирает четыре вида, условия местоименной связи, возможность различия в определённости и замену имени, глагола либо целого предложения.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Четыре вида الْبَدَلُ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّرْطُ أَوِ الْمَعْنَى</span><span class="rule-table-ru">условие или смысл</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بَدَلُ كُلٍّ مِنْ كُلٍّ</span><span class="rule-table-ru">полная замена</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْبَدَلُ هُوَ نَفْسُ الْمُبْدَلِ مِنْهُ</span><span class="rule-table-ru">оба обозначают один и тот же предмет</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">جَاءَ أَخُوكَ هَاشِمٌ.</span><span class="rule-table-ru">Пришёл твой брат Хашим.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بَدَلُ بَعْضٍ مِنْ كُلٍّ</span><span class="rule-table-ru">замена части целого</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جُزْءٌ حَقِيقِيٌّ وَفِيهِ ضَمِيرٌ يَعُودُ إِلَى الْمُبْدَلِ مِنْهُ</span><span class="rule-table-ru">реальная часть с местоимением, возвращающимся к целому</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">أَكَلْتُ التُّفَّاحَةَ نِصْفَهَا.</span><span class="rule-table-ru">Я съел половину яблока.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بَدَلُ اشْتِمَالٍ</span><span class="rule-table-ru">замена по смысловой включённости</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَيْسَ جُزْءًا حَقِيقِيًّا، وَفِيهِ ضَمِيرٌ يَعُودُ إِلَى الْمُبْدَلِ مِنْهُ</span><span class="rule-table-ru">не является физической частью, но содержит возвращающееся местоимение</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَعْجَبَنِي الْخَطِيبُ عِلْمُهُ.</span><span class="rule-table-ru">Мне понравилось знание проповедника.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بَدَلُ الْمُبَايِنِ</span><span class="rule-table-ru">замена несоответствующего</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بَدَلُ الْغَلَطِ أَوِ النِّسْيَانِ</span><span class="rule-table-ru">исправление оговорки или забывчивости</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">عَاصِمَةُ الْمَمْلَكَةِ جِدَّةُ، الرِّيَاضُ.</span><span class="rule-table-ru">Столица Королевства — Джидда… Эр-Рияд.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранические примеры четырёх положений</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿ٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ ۝ صِرَٰطَ ٱلَّذِينَ أَنۡعَمۡتَ عَلَيۡهِمۡ﴾</span><span class="rule-example-ru">Веди нас прямым путём — путём тех, кого Ты облагодетельствовал. Второе الصِّرَاطَ полностью заменяет первое.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿ثُمَّ عَمُواْ وَصَمُّواْ كَثِيرٞ مِّنۡهُمۡ﴾</span><span class="rule-example-ru">Затем многие из них вновь ослепли и оглохли. كَثِيرٌ — بَدَلُ بَعْضٍ مِنْ كُلٍّ.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿يَسۡـَٔلُونَكَ عَنِ ٱلشَّهۡرِ ٱلۡحَرَامِ قِتَالٖ فِيهِ﴾</span><span class="rule-example-ru">Они спрашивают тебя о запретном месяце — о сражении в нём. قِتَالٍ — بَدَلُ اشْتِمَالٍ.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿لَنَسۡفَعَۢا بِٱلنَّاصِيَةِ ۝ نَاصِيَةٖ كَٰذِبَةٍ خَاطِئَةٖ﴾</span><span class="rule-example-ru">Мы непременно схватим его за хохол — хохол лживый, грешный. Нельзя требовать одинаковой определённости у обоих членов.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿ٱللَّهُ نَزَّلَ أَحۡسَنَ ٱلۡحَدِيثِ كِتَٰبٗا﴾</span><span class="rule-example-ru">Аллах ниспослал наилучшую речь — Писание. К определённому الْحَدِيثِ относится неопределённое كِتَابًا.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Что может заменяться</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الصُّورَةُ</span><span class="rule-table-ru">вид замены</span></th><th><span class="rule-table-ar ar-tone-default" dir="rtl" lang="ar">الشَّاهِدُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْبَيَانُ</span><span class="rule-table-ru">пояснение по шарху</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اسْمٌ مِنِ اسْمٍ</span><span class="rule-table-ru">имя заменяет имя</span></td><td><span class="rule-table-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿يَسۡـَٔلُونَكَ عَنِ ٱلشَّهۡرِ ٱلۡحَرَامِ قِتَالٖ فِيهِ﴾</span><span class="rule-table-ru">о запретном месяце — сражении в нём</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قِتَالٍ بَدَلٌ مِنَ الشَّهْرِ الْحَرَامِ</span><span class="rule-table-ru">قِتَالٍ заменяет الشَّهْرِ الْحَرَامِ</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فِعْلٌ مِنْ فِعْلٍ</span><span class="rule-table-ru">глагол заменяет глагол</span></td><td><span class="rule-table-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿وَمَن يَفۡعَلۡ ذَٰلِكَ يَلۡقَ أَثَامٗا ۝ يُضَٰعَفۡ لَهُ ٱلۡعَذَابُ﴾</span><span class="rule-table-ru">Кто совершит это, встретит воздаяние; ему будет удвоено наказание.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يُضَاعَفْ بَدَلٌ مِنْ يَلْقَ</span><span class="rule-table-ru">يُضَاعَفْ заменяет يَلْقَ</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جُمْلَةٌ مِنْ جُمْلَةٍ</span><span class="rule-table-ru">предложение заменяет предложение</span></td><td><span class="rule-table-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿أَمَدَّكُم بِمَا تَعۡلَمُونَ ۝ أَمَدَّكُم بِأَنۡعَٰمٖ وَبَنِينَ﴾</span><span class="rule-table-ru">Он поддержал вас тем, что вы знаете; поддержал вас скотом и сыновьями.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَمَدَّكُمْ الثَّانِيَةُ بَدَلٌ مِنَ الْأُولَى</span><span class="rule-table-ru">второе предложение с أَمَدَّكُمْ заменяет первое</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جُمْلَةٌ مِنِ اسْمٍ مُفْرَدٍ</span><span class="rule-table-ru">предложение заменяет отдельное имя</span></td><td><span class="rule-table-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿أَفَلَا يَنظُرُونَ إِلَى ٱلۡإِبِلِ كَيۡفَ خُلِقَتۡ﴾</span><span class="rule-table-ru">Неужели они не смотрят на верблюдов, как они созданы?</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كَيْفَ خُلِقَتْ بَدَلٌ مِنَ الْإِبِلِ</span><span class="rule-table-ru">предложение كَيْفَ خُلِقَتْ заменяет имя الْإِبِلِ</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный разбор جَاءَ أَخُوكَ مُحَمَّدٌ</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">جَاءَ: فِعْلٌ مَاضٍ مَبْنِيٌّ عَلَى الْفَتْحِ.</span><span class="rule-example-ru">جَاءَ — глагол прошедшего времени, неизменяемый на фатхе.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">أَخُوكَ: فَاعِلٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الْوَاوُ، وَهُوَ مُضَافٌ، وَكَافُ الْمُخَاطَبِ مَبْنِيَّةٌ عَلَى الْفَتْحِ فِي مَحَلِّ جَرٍّ مُضَافٌ إِلَيْهِ.</span><span class="rule-example-ru">أَخُوكَ — исполнитель действия в именительном статусе с признаком و; первая часть идафы. ك — местоимение адресата, неизменяемое на фатхе в родительном месте второй части идафы.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar ar-tone-raf" dir="rtl" lang="ar">مُحَمَّدٌ: بَدَلُ كُلٍّ مِنْ كُلٍّ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">مُحَمَّدٌ — полная замена в именительном статусе с явной даммой.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный разбор انْتَفَعْتُ بِالْقُرْآنِ هَدْيِهِ</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">انْتَفَعْتُ: فِعْلٌ مَاضٍ مَبْنِيٌّ عَلَى السُّكُونِ لِاتِّصَالِهِ بِالتَّاءِ الْمُتَحَرِّكَةِ، وَالتَّاءُ ضَمِيرُ رَفْعٍ مُتَّصِلٌ مَبْنِيٌّ عَلَى الضَّمِّ فِي مَحَلِّ رَفْعٍ فَاعِلٌ.</span><span class="rule-example-ru">انْتَفَعْتُ — глагол прошедшего времени, построенный на сукуне из-за присоединения подвижной ت; ت — слитное местоимение в именительном месте исполнителя.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar ar-tone-jarr" dir="rtl" lang="ar">بِالْقُرْآنِ: الْبَاءُ حَرْفُ جَرٍّ مَبْنِيٌّ عَلَى الْكَسْرِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَالْقُرْآنِ اسْمٌ مَجْرُورٌ بِالْبَاءِ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">بِـ — неизменяемый на касре предлог без синтаксического места; الْقُرْآنِ — имя в родительном статусе после بِـ с явной касрой.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar ar-tone-jarr" dir="rtl" lang="ar">هَدْيِهِ: بَدَلُ اشْتِمَالٍ مَجْرُورٌ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ، وَهُوَ مُضَافٌ، وَهَاءُ الْغَيْبَةِ مَبْنِيَّةٌ عَلَى الْكَسْرِ فِي مَحَلِّ جَرٍّ مُضَافٌ إِلَيْهِ.</span><span class="rule-example-ru">هَدْيِهِ — بَدَلُ اشْتِمَالٍ в родительном статусе с касрой и первая часть идафы; ه — местоимение отсутствующего лица в родительном месте второй части идафы.</span></div></div></div></div>', 'الْبَدَلُ — зависимый член, на который непосредственно направлено сообщение. Шарх разбирает четыре вида, условия местоименной связи, возможность различия в определённости и замену имени, глагола либо целого предложения.', 'الْبَدَلُ تَابِعٌ مَقْصُودٌ بِالْحُكْمِ بِلَا وَاسِطَةٍ بَيْنَهُ وَبَيْنَ مَتْبُوعِهِ. وَأَنْوَاعُهُ: بَدَلُ كُلٍّ مِنْ كُلٍّ، وَبَدَلُ بَعْضٍ مِنْ كُلٍّ، وَبَدَلُ اشْتِمَالٍ، وَبَدَلُ الْمُبَايِنِ. وَلَا يُشْتَرَطُ اتِّفَاقُ الْبَدَلِ وَالْمُبْدَلِ مِنْهُ فِي التَّعْرِيفِ وَالتَّنْكِيرِ.'),
    (8, 'الْأَحْرُفُ الْمُشَبَّهَةُ بِالْفِعْلِ (частицы, подобные глаголу)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">الْأَحْرُفُ الْمُشَبَّهَةُ بِالْفِعْلِ هِيَ إِنَّ وَأَنَّ وَكَأَنَّ وَلَكِنَّ وَلَيْتَ وَلَعَلَّ، وَتَنْصِبُ الِاسْمَ وَتَرْفَعُ الْخَبَرَ. يَكُونُ خَبَرُهَا مُفْرَدًا، أَوْ جُمْلَةً فِعْلِيَّةً، أَوِ اسْمِيَّةً، أَوْ شِبْهَ جُمْلَةٍ. وَلَا يَتَقَدَّمُ خَبَرُهَا عَلَيْهَا وَلَا عَلَى اسْمِهَا، إِلَّا إِذَا كَانَ شِبْهَ جُمْلَةٍ؛ فَيَجُوزُ تَقْدِيمُهُ إِذَا كَانَ اسْمُهَا مَعْرِفَةً، وَيَجِبُ إِذَا كَانَ نَكِرَةً. وَيَجُوزُ دُخُولُ نُونِ الْوِقَايَةِ عَلَى إِنَّ وَأَنَّ وَلَكِنَّ وَكَأَنَّ، وَلَا تُحْذَفُ نُونُ الْوِقَايَةِ مِنْ لَيْتَ إِلَّا نَادِرًا، وَيَقِلُّ دُخُولُهَا عَلَى لَعَلَّ.</span><p class="rule-study-text">Шесть частиц ставят имя в винительный, а сказуемое — в именительный статус. Сказуемое бывает отдельным словом, глагольным или именным предложением и شِبْهُ جُمْلَةٍ. Его вынесение регулируется видом сказуемого и определённостью имени.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Значение каждой частицы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْحَرْفُ</span><span class="rule-table-ru">частица</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">арабский термин</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّرْحُ بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русское значение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِنَّ وَأَنَّ</span><span class="rule-table-ru">إِنَّ и أَنَّ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّأْكِيدُ</span><span class="rule-table-ru">усиление, подтверждение</span></td><td><span class="rule-table-ru">подчёркивают достоверность сообщения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">كَأَنَّ</span><span class="rule-table-ru">كَأَنَّ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّشْبِيهُ</span><span class="rule-table-ru">уподобление</span></td><td><span class="rule-table-ru">«словно, как будто»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَكِنَّ</span><span class="rule-table-ru">لَكِنَّ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الِاسْتِدْرَاكُ</span><span class="rule-table-ru">поправка, противопоставление</span></td><td><span class="rule-table-ru">«однако, но»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَيْتَ</span><span class="rule-table-ru">لَيْتَ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّمَنِّي</span><span class="rule-table-ru">пожелание</span></td><td><span class="rule-table-ru">пожелание возможного или невозможного</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَعَلَّ</span><span class="rule-table-ru">لَعَلَّ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرَجِّي</span><span class="rule-table-ru">надежда, ожидание</span></td><td><span class="rule-table-ru">ожидание того, что может осуществиться</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Работа и отличие لَيْتَ от لَعَلَّ</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar ar-tone-nasb" dir="rtl" lang="ar">تَنْصِبُ الِاسْمَ وَتَرْفَعُ الْخَبَرَ</span><span class="rule-term-ru">ставят имя в винительный, а сказуемое в именительный статус</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">لَعَلَّ لِلْمُمْكِنِ حُصُولُهُ</span><span class="rule-term-ru">لَعَلَّ относится к тому, что может осуществиться</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">لَيْتَ لِلْمُمْكِنِ وَغَيْرِ الْمُمْكِنِ</span><span class="rule-term-ru">لَيْتَ употребляется для возможного и невозможного</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">يَجُوزُ أَنْ يَكُونَ اسْمُهَا نَكِرَةً</span><span class="rule-term-ru">их имя может быть неопределённым</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Четыре формы сказуемого</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">نَوْعُ الْخَبَرِ</span><span class="rule-table-ru">вид сказуемого</span></th><th><span class="rule-table-ar ar-tone-default" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُفْرَدٌ</span><span class="rule-table-ru">отдельное слово</span></td><td><span class="rule-table-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ﴾</span><span class="rule-table-ru">Поистине, Аллах — Прощающий, Милующий.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">جُمْلَةٌ فِعْلِيَّةٌ</span><span class="rule-table-ru">глагольное предложение</span></td><td><span class="rule-table-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿إِنَّ ٱللَّهَ يَغۡفِرُ ٱلذُّنُوبَ جَمِيعًا﴾</span><span class="rule-table-ru">Поистине, Аллах прощает все грехи.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">جُمْلَةٌ اسْمِيَّةٌ</span><span class="rule-table-ru">именное предложение</span></td><td><span class="rule-table-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿إِنَّ ٱللَّهَ عِندَهُۥ عِلۡمُ ٱلسَّاعَةِ﴾</span><span class="rule-table-ru">Поистине, у Аллаха — знание о Часе.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">شِبْهُ جُمْلَةٍ</span><span class="rule-table-ru">предложная группа или обстоятельство</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">إِنَّ الطَّالِبَ فِي الْفَصْلِ. إِنَّ الطَّائِرَ فَوْقَ الشَّجَرَةِ.</span><span class="rule-table-ru">Студент находится в аудитории. Птица находится над деревом.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Положение сказуемого</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحَالَةُ</span><span class="rule-table-ru">случай</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحُكْمُ</span><span class="rule-table-ru">правило</span></th><th><span class="rule-table-ar ar-tone-default" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَصْلُ</span><span class="rule-table-ru">обычное положение</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لَا يَتَقَدَّمُ الْخَبَرُ عَلَى الْحَرْفِ وَلَا عَلَى اسْمِهِ</span><span class="rule-table-ru">сказуемое не выносится перед частицей или её именем</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِنَّ اللَّهَ غَفُورٌ.</span><span class="rule-table-ru">Поистине, Аллах — Прощающий.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">شِبْهُ جُمْلَةٍ وَالِاسْمُ مَعْرِفَةٌ</span><span class="rule-table-ru">сказуемое شِبْهُ جُمْلَةٍ, имя определённое</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يَجُوزُ تَقْدِيمُ الْخَبَرِ</span><span class="rule-table-ru">сказуемое разрешается вынести</span></td><td><span class="rule-table-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿إِنَّ إِلَيۡنَآ إِيَابَهُمۡ ۝ ثُمَّ إِنَّ عَلَيۡنَا حِسَابَهُم﴾</span><span class="rule-table-ru">Поистине, к Нам их возвращение; затем на Нас их расчёт.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">شِبْهُ جُمْلَةٍ وَالِاسْمُ نَكِرَةٌ</span><span class="rule-table-ru">сказуемое شِبْهُ جُمْلَةٍ, имя неопределённое</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يَجِبُ تَقْدِيمُ الْخَبَرِ</span><span class="rule-table-ru">сказуемое обязательно выносится</span></td><td><span class="rule-table-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿إِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرٗا﴾</span><span class="rule-table-ru">Поистине, с трудностью — облегчение.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">شِبْهُ جُمْلَةٍ وَالِاسْمُ نَكِرَةٌ</span><span class="rule-table-ru">сказуемое شِبْهُ جُمْلَةٍ, имя неопределённое</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يَجِبُ تَقْدِيمُ الْخَبَرِ</span><span class="rule-table-ru">сказуемое обязательно выносится</span></td><td><span class="rule-table-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿إِنَّ لَدَيۡنَآ أَنكَالٗا﴾</span><span class="rule-table-ru">Поистине, у Нас — оковы.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Нُونُ الْوِقَايَةِ — защитная ن</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْحَرْفُ</span><span class="rule-table-ru">частица</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَعَ نُونِ الْوِقَايَةِ</span><span class="rule-table-ru">с защитной ن</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بِحَذْفِهَا</span><span class="rule-table-ru">без неё</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحُكْمُ</span><span class="rule-table-ru">употребление</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِنَّ</span><span class="rule-table-ru">إِنَّ</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِنَّنِي</span><span class="rule-table-ru">поистине, я</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">إِنِّي</span><span class="rule-table-ru">поистине, я</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">يَجُوزُ الْوَجْهَانِ</span><span class="rule-table-ru">обе формы допустимы</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَنَّ</span><span class="rule-table-ru">أَنَّ</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَنَّنِي</span><span class="rule-table-ru">что я</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَنِّي</span><span class="rule-table-ru">что я</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">يَجُوزُ الْوَجْهَانِ</span><span class="rule-table-ru">обе формы допустимы</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَكِنَّ</span><span class="rule-table-ru">لَكِنَّ</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَكِنَّنِي</span><span class="rule-table-ru">однако я</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَكِنِّي</span><span class="rule-table-ru">однако я</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">يَجُوزُ الْوَجْهَانِ</span><span class="rule-table-ru">обе формы допустимы</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">كَأَنَّ</span><span class="rule-table-ru">كَأَنَّ</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">كَأَنَّنِي</span><span class="rule-table-ru">словно я</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">كَأَنِّي</span><span class="rule-table-ru">словно я</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">يَجُوزُ الْوَجْهَانِ</span><span class="rule-table-ru">обе формы допустимы</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَيْتَ</span><span class="rule-table-ru">لَيْتَ</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَيْتَنِي</span><span class="rule-table-ru">о, если бы я</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَيْتِي</span><span class="rule-table-ru">редкая форма</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَا تُحْذَفُ إِلَّا نَادِرًا</span><span class="rule-table-ru">ن удаляется только редко</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَعَلَّ</span><span class="rule-table-ru">لَعَلَّ</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَعَلَّنِي</span><span class="rule-table-ru">возможно, я</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَعَلِّي</span><span class="rule-table-ru">возможно, я</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">يَقِلُّ دُخُولُهَا</span><span class="rule-table-ru">защитная ن присоединяется редко</span></td></tr></tbody></table></div></div></div>', 'Шесть частиц ставят имя в винительный, а сказуемое — в именительный статус. Сказуемое бывает отдельным словом, глагольным или именным предложением и شِبْهُ جُمْلَةٍ. Его вынесение регулируется видом сказуемого и определённостью имени.', 'الْأَحْرُفُ الْمُشَبَّهَةُ بِالْفِعْلِ هِيَ إِنَّ وَأَنَّ وَكَأَنَّ وَلَكِنَّ وَلَيْتَ وَلَعَلَّ، وَتَنْصِبُ الِاسْمَ وَتَرْفَعُ الْخَبَرَ. يَكُونُ خَبَرُهَا مُفْرَدًا، أَوْ جُمْلَةً فِعْلِيَّةً، أَوِ اسْمِيَّةً، أَوْ شِبْهَ جُمْلَةٍ. وَلَا يَتَقَدَّمُ خَبَرُهَا عَلَيْهَا وَلَا عَلَى اسْمِهَا، إِلَّا إِذَا كَانَ شِبْهَ جُمْلَةٍ؛ فَيَجُوزُ تَقْدِيمُهُ إِذَا كَانَ اسْمُهَا مَعْرِفَةً، وَيَجِبُ إِذَا كَانَ نَكِرَةً. وَيَجُوزُ دُخُولُ نُونِ الْوِقَايَةِ عَلَى إِنَّ وَأَنَّ وَلَكِنَّ وَكَأَنَّ، وَلَا تُحْذَفُ نُونُ الْوِقَايَةِ مِنْ لَيْتَ إِلَّا نَادِرًا، وَيَقِلُّ دُخُولُهَا عَلَى لَعَلَّ.'),
    (9, 'جَمْعُ أَفْعَلَ الَّذِي مُؤَنَّثُهُ فَعْلَاءُ (множественное أَفْعَلُ / فَعْلَاءُ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">أَفْعَلُ الَّذِي مُؤَنَّثُهُ فَعْلَاءُ يُجْمَعُ عَلَى فُعْلٍ لِلْمُذَكَّرِ وَالْمُؤَنَّثِ.</span><p class="rule-study-text">Прилагательное модели أَفْعَلُ с женской формой فَعْلَاءُ образует общее для мужчин и женщин множественное по модели فُعْلٌ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Формы мужского, женского и множественного</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُذَكَّرُ</span><span class="rule-table-ru">мужской род</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمُؤَنَّثُ</span><span class="rule-table-ru">женский род</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجَمْعُ لِلْجِنْسَيْنِ</span><span class="rule-table-ru">множественное для обоих родов</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَعْرَجُ</span><span class="rule-table-ru">хромой мужчина</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">عَرْجَاءُ</span><span class="rule-table-ru">хромая женщина</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">عُرْجٌ</span><span class="rule-table-ru">хромые мужчины или женщины</span></td><td><span class="rule-table-ru">одно множественное для обоих родов</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَبْكَمُ</span><span class="rule-table-ru">немой мужчина</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">بَكْمَاءُ</span><span class="rule-table-ru">немая женщина</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بُكْمٌ</span><span class="rule-table-ru">немые мужчины или женщины</span></td><td><span class="rule-table-ru">одно множественное для обоих родов</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَعْوَرُ</span><span class="rule-table-ru">одноглазый мужчина</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">عَوْرَاءُ</span><span class="rule-table-ru">одноглазая женщина</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">عُورٌ</span><span class="rule-table-ru">одноглазые мужчины или женщины</span></td><td><span class="rule-table-ru">одно множественное для обоих родов</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Предложения шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">هَذَا الرَّجُلُ أَعْرَجُ. هَذِهِ الْمَرْأَةُ عَرْجَاءُ.</span><span class="rule-example-ru">Этот мужчина хромой. Эта женщина хромая.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar ar-tone-structure" dir="rtl" lang="ar">هَؤُلَاءِ الرِّجَالُ عُرْجٌ. هَؤُلَاءِ النِّسَاءُ عُرْجٌ.</span><span class="rule-example-ru">Эти мужчины хромые. Эти женщины хромые.</span></div></div></div></div>', 'Прилагательное модели أَفْعَلُ с женской формой فَعْلَاءُ образует общее для мужчин и женщин множественное по модели فُعْلٌ.', 'أَفْعَلُ الَّذِي مُؤَنَّثُهُ فَعْلَاءُ يُجْمَعُ عَلَى فُعْلٍ لِلْمُذَكَّرِ وَالْمُؤَنَّثِ.')
)
update public.rules as r
set title = incoming.title,
    content = incoming.content,
    rule_kind = 'rule',
    summary = incoming.summary,
    rule_ar = incoming.rule_ar
from incoming
where r.course_name = 'Мединский курс (Том 4)'
  and r.lesson_number = '4'
  and r.sort_order = incoming.sort_order;

delete from public.rule_sources
where rule_id in (
  select id from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '4'
);

