| يجوز حذف إحدى التاءين إذا كان الفعل مضارعا مبدوءاً بالتاء , نحو قوله تعالى :
﴿ وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ ﴾ والأصل : ولا تَتَعاونوا . ومنه قوله تعالى :
﴿ وَلَا تَنَابَزُوا بِالْأَلْقَابِ ﴾ والأصل : ولا تَتَنابزوا  .', 13, 14, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '4' and sort_order = 1;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'حذفُ حرفِ الجرِّ قبلَ المصدرِ الْمُؤَوَّلِ
يجوز حذف حرف الجر الواقع قبل المصدر المؤوَّل .
نحو : أمرنا الله أن نصلي، والتقدير: بأن نصلي، ونحو : أعوذ بالله أن أكون من الجاهلين،
والتقدير: مِنْ أَنْ أَكُونَ من الجاهلين. ومنه قوله تعالى: ﴿ شَهِدَ اللَّهُ أَنَّهُ لَا إِلَهَ إِلَّا هُوَ ﴾ أي : بِأنَّه لا إله إلا هو .', 14, 14, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '4' and sort_order = 2;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
