insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'مَعْنَى لَيْتَ
تفيد ليت : التَّمَنَّي ، وهو نوعان :
1- طَلَبُ مَالاَ طَمَعَ فِيهِ ، أي لا يمكن الحصول عليه ، نحو قوله تعالى : ﴿ يَا لَيْتَنِي كُنْتُ تُرَابًا ﴾ ونحو قولك : ليتني طائرٌ ، ونحو : ليت الشَّبَابَ يعودُ .
2- ما فيه عُسْرٌ ، أي يمكن  الحصول عليه ولكنه صعب الآن ، نحو قول الفقير :
ليت لي مالاً كثيراً ، ونحو : ليتني عَالِمٌ .', 15, 15, 1
