insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'لا النَّافِيَةُ لِلْجِنْسِ
معناها : تنفي الحكمَ عن كلِّ جِنْسِ اسمِها .
عملُها : تعملُ عملَ إِنَّ ، أي : تنصب الاسم ، وترفع الخبر .
شروطُها :
1- أن تحتفظ بالترتيب الأصلي للجملة ، الاسم أولاً ، والخبر ثانيا .
2- أن يكون اسمها وخبرها نكرتين .
3- ألاَّ تقترن بحرف جر .
أنواعُ اسمِها :
1- المضافُ : وهو منصوب ، نحو : لا طالبَ علمٍ مَكْرُوهٌ .
2- الشَّبِيهُ بالمضافِ : وهو منصوب ، نحو : لا طالباً العلمَ مكروهٌ .
( ذُكِرَ هذان النوعان لِلْعِلْمِ بهما فقط ) .
3- المفردُ ، وهو موضوع دراستنا . والمراد بالمفرد : ما ليس مُضَافاً، ولا شَبِيهاً بالمضاف.
حكم المفرد : الِبنَاءُ على ما يُنْصَبُ به .
يُبْنَى اسم لا المفرد على ما ينصب به ، أي : يُنْظَرُ إلى علامة نصبه قبل دخول لا النافية للجنس ، فإن كانت الفتحة فعلامة بنائه الفتحة ، وإن كانت الكسرة فعلامة بنائه الكسرة ... وهكذا ، نحو : لا طالبَ في الفصل ، لا مُسْلِمَاتِ مُتَبَرَّجَاتٌ ، لا مُسْلِمِينَ كَاذِبُونَ .
ونحو قوله تعالى: ﴿ ذَلِكَ الْكِتَابُ لَا رَيْبَ فِيهِ ﴾ وقوله تعالى : ﴿ لَا إِكْرَاهَ فِي الدِّينِ ﴾ .
الإعراب :
لا إكراهَ في الدينِ .
لا : حرف لنفي الجنس مبني على السكون لا محل له من الإعراب .
إكراهَ : اسم لا النافية للجنس مبني على الفتح في محل نصب .
في الدينِ : الجار والمجرور في محل رفع خبر لا النافية للجنس
لا مسلماتِ سَافِرَاتٌ .
لا : حرف لنفي الجنس مبني على السكون لا محل له من الإعراب .
مسلماتِ : اسم لا النافية للجنس مبني على الكسرة في محل نصب .
سافراتٌ : خبر لا النافية للجنس مرفوع وعلامة رفعه الضمة الظاهرة .', 15, 16, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '4' and sort_order = 6;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'الْبَدَلُ
البدلُ ، هو : التَّابِعُ المقصودُ بالحكمِ بلا واسطةٍ بينَه وبينَ متبوعِه .
أنواعـه :
1- بَدَلُ كُلٍّ مِن كُلٍّ : نحو : جاء أخوك هاشمٌ . هذا هو الخليفةُ أبو بكرٍ رضي الله عنه.
ومنه قوله تعالى : ﴿ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ۝ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ ﴾ .
2- بدلُ بَعْضٍ من كلٍّ : يشترط أن يكون جزءا حقيقيا من المبدل منه , ويشتمل على ضمير يعود إلى المبدل منه .
نحو : أكلتُ التفاحةَ نصفَها . عالج الطبيبُ المريضَ أنفَه . ومنه قوله تعالى :
﴿ ثُمَّ عَمُوا وَصَمُّوا كَثِيرٌ مِنْهُمْ ﴾ .
3- بدلُ الاشْتِمَالِ : يشترط أن يشتمل على ضمير يعود إلى المبدل منه , وهو ليس جزءاً حقيقياً من المبدل منه ، نحو : أعجبني الخطيبُ عِلْمُهُ .  انتفعتُ بالقرآنِ هَدْيِهِ .
ومنه قوله تعالى : ﴿ يَسْأَلُونَكَ عَنِ الشَّهْرِ الْحَرَامِ قِتَالٍ فِيهِ ﴾ .
4- بدلُ الْمُبَايِنِ ، وهو بدلُ الْغَلَطِ ، أو النَّسْيَانِ ( يقع كثيراً في الكلام المنطوق )
نحو : عاصمة المملكة جدةُ الرياضُ . صليت في المسجد النبويّ الظهرَ العصرَ .
لا يُشترط في البدل : أن يتبع المبدل منه في التنكير ، والتعريف، نحو قوله تعالى :
﴿ لَنَسْفَعًا بِالنَّاصِيَةِ ۝ نَاصِيَةٍ كَاذِبَةٍ خَاطِئَةٍ ﴾ .
فـ ( ناصيةٍ ) بدل وهو نكرة والمبدل منه ( الناصية ) وهو معرفة . ومنه قوله تعالى : ﴿ اللَّهُ نَزَّلَ أَحْسَنَ الْحَدِيثِ كِتَابًا ﴾  .
* يبدل الاسم من الاسم , كما في قوله تعالى: ﴿ يَسْأَلُونَكَ عَنِ الشَّهْرِ الْحَرَامِ قِتَالٍ فِيهِ ﴾
فـ ( قِتَالٍ ) بدل من ( الشهر الحرام ) وكلاهما اسمٌ مفرد .
ويبدل الفعل من الفعل , كما في قوله تعالى: ﴿ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا ۝ يُضَاعَفْ لَهُ الْعَذَابُ ﴾ فـ ( يضاعفْ ) بدل من( يلقَ ) وكلاهما فعل .
وتبدل الجملة من الجملة ,كما في قوله تعالى: ﴿ أَمَدَّكُمْ بِمَا تَعْلَمُونَ ۝ أَمَدَّكُمْ بِأَنْعَامٍ وَبَنِينَ ﴾ ،
فـ ( أمدّكم ) الثانية بدل من ( أمدّكم ) الأولى , وكلاهما جملة .
وتبدل الجملة من الاسم المفرد, كما في قوله تعالى : ﴿ أَفَلَا يَنْظُرُونَ إِلَى الْإِبِلِ كَيْفَ خُلِقَتْ ﴾ فجملة ( كيف خلقت ) بدل من الاسم المفرد ( الإبل ) .
الإعراب : جاء أخوك محمدٌ .
جاء : فعل ماضٍ مبني على الفتح .
أخوك : فاعل مرفوع وعلامة رفعه الواو ، وهو مضاف ، وضمير المخاطب (الكاف)
مبني على الفتح في محلِّ جرّ مضاف إليه .
محمدٌ : بدل كلّ من كلّ مرفوع وعلامة رفعه الضمة الظاهرة .
انتفعت بالقرآنِ هَدْيِهِ .
انتفعت : فعل ماضٍ مبني على السكون لاتَّصاله بالتاء المتحركة ، والتاء : ضمير رفع
متصل مبني على الضم في محل رفع فاعل .
بالقرآنِ : الباء حرف جرّ مبني على الكسر لا محل له من الإعراب .
القرآن : اسم مجرور بالباء وعلامة جرّه الكسرة الظاهرة .
هَدْيِهِ : بدل اشتمال مجرور وعلامة جره الكسرة ، وهو مضاف ، والضمير ( هاء الغيبة )
مبني على الكسر في محل جر مضاف إليه .', 16, 19, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '4' and sort_order = 7;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'الأحرفُ الْمُشَبَّهَةُ بِالْفِعْلِ
معناها : إنَّ ، وأنَّ ( لِلتَّأْكِيدِ ) كَأَنَّ ( لِلتَّشْبِيهِ ) لَكِنَّ ( لِلاْسْتِدْرَاكِ ) لَيْتَ ( للتَّمَنَّي )
لَعَلَّ ( للتَّرَجَّي ) .
الفرق بين ليتَ ، ولعلَّ : التَّرَجَّي ( لعلَّ ) يكون فيما يُمْكِنُ حصوله ، أما التَّمني ( ليت ) فيكون لِلْمُمْكِنِ حُصُولُه ، وغير الممكن .
عملها : تنصب الاسم ، وترفع الخبر .
أحكامها :
أ- يجوز أن يكون اسمها نكرة ، نحو : كأنَّ شيئاً لم يحدث .
ب- خبرها يكون مفردا ، وجملة فعلية واسمية ، وشبه جملة .
نحو قوله تعالى: ﴿ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ ﴾ وقوله تعالى: ﴿ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا ﴾
وقوله تعالى : ﴿ إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ ﴾ إنَّ الطالبَ في الفصلِ . إنَّ الطائرَ فوقَ الشجرةِ .
ج- لا يجوز  أن يتقدم خبرها عليها ، ولا على اسمها ؛ فلا يجوز قولك : غفورٌ إنَّ اللهَ ، ولا يجوز : إنَّ غفورٌ اللهَ .
يجوز أن يتقدم خبرها إذا كان شبه جملة ، واسمها معرفة .
نحو قوله تعالى : ﴿ إِنَّ إِلَيْنَا إِيَابَهُمْ ۝ ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُمْ ﴾ ونحو قولك : إِنَّ في قُلُوبِنَا الإيمانَ .
ويجب تقديم الخبر إذا كان شبه جملة ، واسم إنَّ نكرة .
نحو قوله تعالى : ﴿ إِنَّ مَعَ الْعُسْرِ يُسْرًا ﴾ وقوله تعالى : ﴿ إِنَّ لَدَيْنَا أَنْكَالًا ﴾
ونحو قولك : إنَّ في القَلْبِ إيماناً .
دخولُ نُونِ الْوِقَايَةِ عليها .
يجوز دخول نون الوقاية على إنَّ ، وأنَّ ، ولَكِنَّ ، وكَأَنَّ .
تقول : إنَّنِي ، وإنِّي - أنَّني ، وأنِّي - لكنَّني ، ولكنِّي - كَأَنَّنِي، وكَأنِّي .
أما ليت فلا تحذف منها إلا نادِراً ، وأما لعلَّ فيَقِلُّ دخول نون الوقاية عليها .', 19, 20, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '4' and sort_order = 8;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'جَمْعُ أَفْعَلَ الَّذي مُؤَنَّثُهُ فَعْلاَءُ
أَفْعَل الذي مؤنثه فَعْلاَء , يُجْمَعُ على ( فُعْل ) للمذكر والمؤنث ؛ تقول :
هذا الرَجُلُ أَعْرَجُ . هذه المرأةُ عَرْجَاءُ . هؤلاءِ الرجالُ عُرْجٌ . هؤلاءِ النَّسَاءُ عُرْجٌ .
وتقول: أَبْكَمُ, بَكْمَاءُ ( بُكْمٌ ) للرجال والنساء . أَعْوَرُ, عَوْرَاءُ ( عُوْرٌ ) للرجال والنساء .', 20, 20, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '4' and sort_order = 9;

do $migration$
declare
  updated_count integer;
  source_count integer;
begin
  select count(*) into updated_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '4' and rule_ar is not null and btrim(rule_ar) <> '';
  select count(*) into source_count
  from public.rule_sources rs
  join public.rules r on r.id = rs.rule_id
  where r.course_name = 'Мединский курс (Том 4)' and r.lesson_number = '4';
  if updated_count <> 9 or source_count <> 9 then
    raise exception 'Book 4 lesson 4 QA failed: rules %, sources %', updated_count, source_count;
  end if;
end $migration$;

commit;
